1	package api_test
2	
3	import (
4		"encoding/json"
5		"net/http"
6		"net/http/httptest"
7		"strings"
8		"testing"
9		"time"
10	
11		"example.com/saasapi/internal/api"
12		"example.com/saasapi/internal/store"
13	)
14	
15	func newServer(t *testing.T) (*api.Server, *store.Store) {
16		t.Helper()
17		st := store.New()
18		st.AddAccount(store.Account{ID: "acc_acme", Name: "Acme", Plan: store.PlanFree, TaxRateBP: 825})
19		st.AddAccount(store.Account{ID: "acc_globex", Name: "Globex", Plan: store.PlanPro})
20		st.AddKey("key-acme", "acc_acme")
21		st.AddKey("key-globex", "acc_globex")
22		now := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
23		return api.New(st, api.Options{Now: func() time.Time { return now }}), st
24	}
25	
26	func do(t *testing.T, h http.Handler, method, path, key, body string) *httptest.ResponseRecorder {
27		t.Helper()
28		req := httptest.NewRequest(method, path, strings.NewReader(body))
29		if key != "" {
30			req.Header.Set("X-API-Key", key)
31		}
32		rec := httptest.NewRecorder()
33		h.ServeHTTP(rec, req)
34		return rec
35	}
36	
37	func TestARequestWithoutAValidKeyIsUnauthorized(t *testing.T) {
38		srv, _ := newServer(t)
39		for _, key := range []string{"", "nope"} {
40			if r := do(t, srv, "GET", "/api/customers", key, ""); r.Code != http.StatusUnauthorized {
41				t.Fatalf("key %q: status %d", key, r.Code)
42			}
43		}
44		if r := do(t, srv, "GET", "/healthz", "", ""); r.Code != http.StatusOK {
45			t.Fatalf("healthz: %d", r.Code)
46		}
47	}
48	
49	func TestCreateAndReadACustomer(t *testing.T) {
50		srv, _ := newServer(t)
51		r := do(t, srv, "POST", "/api/customers", "key-acme", `{"name":"Jane Doe","email":"jane@example.com","plan":"pro"}`)
52		if r.Code != http.StatusCreated {
53			t.Fatalf("create: %d %s", r.Code, r.Body)
54		}
55		var c store.Customer
56		if err := json.Unmarshal(r.Body.Bytes(), &c); err != nil || c.ID == "" || c.Plan != store.PlanPro {
57			t.Fatalf("created %+v %v", c, err)
58		}
59		if r := do(t, srv, "GET", "/api/customers/"+c.ID, "key-acme", ""); r.Code != http.StatusOK {
60			t.Fatalf("get: %d", r.Code)
61		}
62		if r := do(t, srv, "POST", "/api/customers", "key-acme", `{"name":"","email":"x"}`); r.Code != http.StatusUnprocessableEntity {
63			t.Fatalf("invalid customer: %d", r.Code)
64		}
65	}
66	
67	func TestAnotherAccountsCustomerIsNotFound(t *testing.T) {
68		srv, st := newServer(t)
69		c, err := st.CreateCustomer("acc_globex", "Hank", "hank@globex.test", store.PlanFree, time.Now())
70		if err != nil {
71			t.Fatal(err)
72		}
73		if r := do(t, srv, "GET", "/api/customers/"+c.ID, "key-acme", ""); r.Code != http.StatusNotFound {
74			t.Fatalf("cross-account read: %d", r.Code)
75		}
76		r := do(t, srv, "GET", "/api/customers", "key-acme", "")
77		if strings.Contains(r.Body.String(), c.ID) {
78			t.Fatalf("another account's customer is listed: %s", r.Body)
79		}
80	}
81	
82	func TestAnInvoiceHasItsTotals(t *testing.T) {
83		srv, st := newServer(t)
84		c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
85		r := do(t, srv, "POST", "/api/invoices", "key-acme", `{"customer_id":"`+c.ID+`","lines":[{"description":"Pro plan","quantity":1,"unit_cents":10000}]}`)
86		if r.Code != http.StatusCreated {
87			t.Fatalf("create invoice: %d %s", r.Code, r.Body)
88		}
89		var v struct {
90			ID     string `json:"id"`
91			Totals struct {
92				TotalCents int64 `json:"total_cents"`
93			} `json:"totals"`
94		}
95		if err := json.Unmarshal(r.Body.Bytes(), &v); err != nil || v.Totals.TotalCents != 10825 {
96			t.Fatalf("invoice %s %v", r.Body, err)
97		}
98		if r := do(t, srv, "GET", "/api/invoices/"+v.ID, "key-globex", ""); r.Code != http.StatusNotFound {
99			t.Fatalf("cross-account invoice: %d", r.Code)
100		}
101	}
102

