122		var in struct {
123			CustomerID    string           `json:"customer_id"`
124			Lines         []store.LineItem `json:"lines"`
125			CouponPercent int              `json:"coupon_percent"`
126			CreditCents   int64            `json:"credit_cents"`
127		}
128		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
129			writeError(w, http.StatusBadRequest, "invalid_json")
130			return
131		}
132		inv, err := s.store.CreateInvoice(store.Invoice{AccountID: acct.ID, CustomerID: in.CustomerID, Lines: in.Lines, CouponPercent: in.CouponPercent, CreditCents: in.CreditCents}, s.now())
133		if err != nil {
134			writeStoreError(w, err)
135			return
136		}
137		writeJSON(w, http.StatusCreated, view(inv))
138	}
