160	func writeStoreError(w http.ResponseWriter, err error) {
161		switch {
162		case errors.Is(err, store.ErrNotFound):
163			writeError(w, http.StatusNotFound, "not_found")
164		case errors.Is(err, store.ErrInvalid):
165			writeError(w, http.StatusUnprocessableEntity, "invalid")
166		default:
167			writeError(w, http.StatusInternalServerError, "internal")
168		}
169	}
